import{az as e,P as i,Q as r,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"框架/微前端/index.md","filePath":"框架/微前端/index.md","lastUpdated":1739235905000}'),t={name:"框架/微前端/index.md"};function o(n,a,s,d,m,f){return i(),r("div",null,[...a[0]||(a[0]=[l('<h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to “概念”">​</a></h2><ol><li>多项目资源共享</li><li>微前端用于集成子应用，所有子应用可以使用任何框架和脚手架</li></ol><h2 id="为什么不是-iframe" tabindex="-1">为什么不是 iframe <a class="header-anchor" href="#为什么不是-iframe" aria-label="Permalink to “为什么不是 iframe”">​</a></h2><p>早期的 layui 用的就是 iframe 开发形式。</p><p>iframe 最大的特性就是提供了浏览器原生的硬隔离方案，不论是<strong>样式隔离</strong>、<strong>js 隔离</strong>这类问题统统都能被完美解决。但他的最大问题也在于他的<strong>隔离性无法被突破</strong>，<strong>导致应用间上下文无法被共享</strong>，随之带来的开发体验、产品体验的问题。</p><ol><li>url 不同步。浏览器刷新 iframe url 状态丢失、后退前进按钮无法使用。</li><li>UI 不同步，DOM 结构不共享。想象一下屏幕右下角 1/4 的 iframe 里来一个带遮罩层的弹框，同时我们要求这个弹框要浏览器居中显示，还要浏览器 resize 时自动居中..</li><li>全局上下文完全隔离，内存变量不共享。iframe 内外系统的通信、数据同步等需求，主应用的 cookie 要透传到根域名都不同的子应用中实现免登效果。</li><li>慢。每次子应用进入都是一次浏览器上下文重建、资源重新加载的过程。</li></ol><h2 id="多应用的疑问" tabindex="-1">多应用的疑问 <a class="header-anchor" href="#多应用的疑问" aria-label="Permalink to “多应用的疑问”">​</a></h2><ol><li>如果多个应用使用了同一个框架如何处理，例如a和b应用都使用lodash</li><li>路由该如何处理</li></ol>',8)])])}const p=e(t,[["render",o]]);export{h as __pageData,p as default};
